import{_ as e,o as a,c as l,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const q=JSON.parse('{"title":"能力圈 Circle of Competence","description":"知道自己知道什么，比知道什么更重要","frontmatter":{"title":"能力圈 Circle of Competence","description":"知道自己知道什么，比知道什么更重要"},"headers":[],"relativePath":"02_concepts/circle-of-competence.md","filePath":"02_concepts/circle-of-competence.md"}'),o={name:"02_concepts/circle-of-competence.md"};function h(s,t,n,i,d,f){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="能力圈-circle-of-competence" tabindex="-1">能力圈 Circle of Competence <a class="header-anchor" href="#能力圈-circle-of-competence" aria-label="Permalink to &quot;能力圈 Circle of Competence&quot;">​</a></h1><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1956-1969</strong></td><td style="text-align:left;">合伙基金基本原则——&quot;不投资自己看不懂的生意&quot;</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1993年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">如何现实地定义自己不知道什么</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1996年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">能力圈边界的经典定义</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1997年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">只买能力圈内的企业，10年持有期</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1999年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">承认科技领域缺乏洞察力</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2000年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">科技行业护城河难持久，偏好传统行业</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2003年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">知道自己不知道什么更重要</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2017年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">错过亚马逊和谷歌——能力圈外的遗憾</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2020年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">苹果属于消费特许经营权，在能力圈内</td></tr></tbody></table><hr><h2 id="_1950s-1960s-基本原则的确立" tabindex="-1">1950s-1960s：基本原则的确立 <a class="header-anchor" href="#_1950s-1960s-基本原则的确立" aria-label="Permalink to &quot;1950s-1960s：基本原则的确立&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的投资生涯从合伙基金时期就开始贯彻能力圈原则。1956年至1969年间，他在合伙基金的基本原则中明确写道：</p><blockquote><p>&quot;我们将不投资自己看不懂的生意。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，合伙基金基本原则（1956-1969）</p></blockquote><p>这不是谦虚，而是投资纪律的根基。在早期投资合伙人有限合伙（Buffett Partnership Ltd.）的13年间，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>始终坚持只在自己理解的领域下注，为日后<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>的长期成功奠定了方法论基础。</p><hr><h2 id="_1990s-能力圈理论的成熟" tabindex="-1">1990s：能力圈理论的成熟 <a class="header-anchor" href="#_1990s-能力圈理论的成熟" aria-label="Permalink to &quot;1990s：能力圈理论的成熟&quot;">​</a></h2><h3 id="_1993年-界定-不知道什么-比-知道什么-更重要" tabindex="-1">1993年：界定&quot;不知道什么&quot;比&quot;知道什么&quot;更重要 <a class="header-anchor" href="#_1993年-界定-不知道什么-比-知道什么-更重要" aria-label="Permalink to &quot;1993年：界定&quot;不知道什么&quot;比&quot;知道什么&quot;更重要&quot;">​</a></h3><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1993年致股东信中，给出了能力圈原则最深刻的诠释之一——重要的不是知识的广度，而是对无知边界的诚实认知：</p><blockquote><p>&quot;对于大多数投资者来说，重要的不是他们知道多少，而是他们如何现实地定义自己不知道什么。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1993年致股东信</p></blockquote><p>这一论述将能力圈从&quot;我知道什么&quot;的正面清单，转化为&quot;我不知道什么&quot;的边界意识。知道自己不知道什么，才是防守型投资的第一道防线。</p><h3 id="_1997年-只买能力圈内的企业" tabindex="-1">1997年：只买能力圈内的企业 <a class="header-anchor" href="#_1997年-只买能力圈内的企业" aria-label="Permalink to &quot;1997年：只买能力圈内的企业&quot;">​</a></h3><p>1997年<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>年度股东大会上，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>进一步明确了操作层面的纪律——买有意义的数量，以10年为持有期：</p><blockquote><p>&quot;你只需要能够评估你能力范围内的公司。只买你理解的企业，买有意义的数量，持有10年。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1997年<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>年度股东大会</p></blockquote><p>这条原则包含三个关键动作：<strong>筛选</strong>（只买理解的企业）、<strong>集中</strong>（买有意义的数量）、<strong>耐心</strong>（10年持有期）。三者缺一不可，都建立在&quot;理解&quot;这个前提之上。</p><h3 id="_1999年-坦然承认科技领域的无知" tabindex="-1">1999年：坦然承认科技领域的无知 <a class="header-anchor" href="#_1999年-坦然承认科技领域的无知" aria-label="Permalink to &quot;1999年：坦然承认科技领域的无知&quot;">​</a></h3><p>1999年是互联网泡沫的巅峰之年，科技股一路狂飙，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>因为不持有科技股而饱受质疑。他在太阳谷演讲中坦诚回应：</p><blockquote><p>&quot;我承认在科技领域缺乏洞察力。我不持有科技股，但我认同科技正在深刻改变社会。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1999年太阳谷演讲</p></blockquote><p>这是能力圈原则最昂贵的坚持——在所有人都在赚钱的领域，公开承认自己不懂。历史证明，正是这种&quot;不懂就不碰&quot;的纪律，让他避开了随后泡沫破裂的毁灭性打击。</p><hr><h2 id="_2000s-科技泡沫的验证与反思" tabindex="-1">2000s：科技泡沫的验证与反思 <a class="header-anchor" href="#_2000s-科技泡沫的验证与反思" aria-label="Permalink to &quot;2000s：科技泡沫的验证与反思&quot;">​</a></h2><h3 id="互联网泡沫后-变化太快-护城河难持久" tabindex="-1">互联网泡沫后：变化太快，护城河难持久 <a class="header-anchor" href="#互联网泡沫后-变化太快-护城河难持久" aria-label="Permalink to &quot;互联网泡沫后：变化太快，护城河难持久&quot;">​</a></h3><p>互联网泡沫破灭后，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对科技行业的谨慎态度得到了验证，但他并没有因此改变立场。他在多个场合解释为什么不投资科技——不是因为轻视，而是因为行业特性让长期确定性判断变得困难：</p><blockquote><p>&quot;科技行业变化太快，护城河很难持久。我更偏好传统行业——那些业务模式可以持续几十年的企业。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2000年代多次发言</p></blockquote><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对科技股的回避，本质上是对&quot;持久竞争优势&quot;（即护城河）可判断性的要求。传统行业的护城河——品牌、渠道、规模效应——可以持续几十年，而科技行业的护城河可能在一轮技术迭代中归零。</p><h3 id="_2003年-知道自己不知道什么更重要" tabindex="-1">2003年：知道自己不知道什么更重要 <a class="header-anchor" href="#_2003年-知道自己不知道什么更重要" aria-label="Permalink to &quot;2003年：知道自己不知道什么更重要&quot;">​</a></h3><p>2003年，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>再次用更精炼的语言重申能力圈的精髓：</p><blockquote><p>&quot;知道自己不知道什么，比知道自己知道什么更重要。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2003年</p></blockquote><p>这句话是1993年论述的浓缩版。投资中最大的风险不是&quot;不知道&quot;，而是&quot;不知道自己不知道&quot;。能力圈的核心价值不在于圈内的知识积累，而在于对圈外区域的自觉回避。</p><hr><h2 id="_2010s-能力圈外的遗憾" tabindex="-1">2010s：能力圈外的遗憾 <a class="header-anchor" href="#_2010s-能力圈外的遗憾" aria-label="Permalink to &quot;2010s：能力圈外的遗憾&quot;">​</a></h2><h3 id="_2017年-错过亚马逊和谷歌" tabindex="-1">2017年：错过亚马逊和谷歌 <a class="header-anchor" href="#_2017年-错过亚马逊和谷歌" aria-label="Permalink to &quot;2017年：错过亚马逊和谷歌&quot;">​</a></h3><p>2017年，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>罕见地公开承认了两个巨大的遗憾——错过了<a href="/search.html?q=亚马逊">亚马逊</a>和<a href="/search.html?q=谷歌">谷歌</a>：</p><blockquote><p>&quot;我错过了亚马逊和谷歌，因为它们不在我的能力圈内。我当初没有预料到亚马逊能做到今天的规模，也没有预料到谷歌的广告模式会如此强大。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2017年<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>年度股东大会</p></blockquote><p>这是能力圈原则的另一面：它保护你不犯大错，但也意味着你会错过圈外的巨大机会。<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对此的态度是坦然接受——错过好公司不亏钱，投了不懂的公司才亏钱。</p><hr><h2 id="_2020s-能力圈的扩展——苹果" tabindex="-1">2020s：能力圈的扩展——苹果 <a class="header-anchor" href="#_2020s-能力圈的扩展——苹果" aria-label="Permalink to &quot;2020s：能力圈的扩展——苹果&quot;">​</a></h2><h3 id="_2020年-苹果是消费特许经营权-在能力圈内" tabindex="-1">2020年：苹果是消费特许经营权，在能力圈内 <a class="header-anchor" href="#_2020年-苹果是消费特许经营权-在能力圈内" aria-label="Permalink to &quot;2020年：苹果是消费特许经营权，在能力圈内&quot;">​</a></h3><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对<a href="/03_companies/苹果公司.html">苹果</a>的大规模投资，是能力圈原则的一次重要演进。他不是&quot;突破&quot;了能力圈，而是对<a href="/03_companies/苹果公司.html">苹果</a>的商业模式做出了重新归类：</p><blockquote><p>&quot;苹果的竞争优势来自生态系统和用户粘性，这属于消费特许经营权——是我能力圈内的。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2020年</p></blockquote><p>这个判断的逻辑链条是：<a href="/03_companies/苹果公司.html">苹果</a>不是一家&quot;科技公司&quot;（靠技术创新驱动），而是一家&quot;消费品公司&quot;（靠用户忠诚度和品牌溢价驱动）。当<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>把<a href="/03_companies/苹果公司.html">苹果</a>从&quot;科技&quot;归类到&quot;消费&quot;时，它自然落入了能力圈内。</p><blockquote><p>&quot;我更倾向于把苹果视为一家消费品公司，而不是一家科技公司。我能理解它的消费者行为，这是最重要的。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2018年</p></blockquote><p>这一归类并非事后合理化。早在2016年首次买入<a href="/03_companies/苹果公司.html">苹果</a>时，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的判断逻辑就是围绕用户忠诚度和重复购买行为展开的——这正是他数十年来评估消费品牌的同一套框架。</p><hr><h2 id="能力圈的演化总结" tabindex="-1">能力圈的演化总结 <a class="header-anchor" href="#能力圈的演化总结" aria-label="Permalink to &quot;能力圈的演化总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">时期</th><th style="text-align:left;">核心态度</th><th style="text-align:left;">代表性原话</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1956-1969</strong></td><td style="text-align:left;">不投资看不懂的生意</td><td style="text-align:left;">&quot;不投资自己看不懂的生意&quot;</td></tr><tr><td style="text-align:left;"><strong>1993</strong></td><td style="text-align:left;">界定不知道什么比知道什么更重要</td><td style="text-align:left;">&quot;重要的不是他们知道多少，而是如何现实地定义自己不知道什么&quot;</td></tr><tr><td style="text-align:left;"><strong>1997</strong></td><td style="text-align:left;">只买圈内的企业，集中持有</td><td style="text-align:left;">&quot;只买你理解的企业，买有意义的数量，持有10年&quot;</td></tr><tr><td style="text-align:left;"><strong>1999</strong></td><td style="text-align:left;">坦然承认科技领域无知</td><td style="text-align:left;">&quot;我承认在科技领域缺乏洞察力&quot;</td></tr><tr><td style="text-align:left;"><strong>2000s</strong></td><td style="text-align:left;">科技护城河难持久</td><td style="text-align:left;">&quot;科技行业变化太快，护城河很难持久&quot;</td></tr><tr><td style="text-align:left;"><strong>2003</strong></td><td style="text-align:left;">不知道自己不知道才是真风险</td><td style="text-align:left;">&quot;知道自己不知道什么，比知道自己知道什么更重要&quot;</td></tr><tr><td style="text-align:left;"><strong>2017</strong></td><td style="text-align:left;">坦然接受圈外的遗憾</td><td style="text-align:left;">&quot;我错过了亚马逊和谷歌，因为不在能力圈内&quot;</td></tr><tr><td style="text-align:left;"><strong>2020</strong></td><td style="text-align:left;">能力圈可以重新归类而非突破</td><td style="text-align:left;">&quot;苹果属于消费特许经营权，是我能力圈内的&quot;</td></tr></tbody></table><hr><h2 id="核心启示" tabindex="-1">核心启示 <a class="header-anchor" href="#核心启示" aria-label="Permalink to &quot;核心启示&quot;">​</a></h2><ol><li><strong>边界比规模更重要</strong>——能力圈的大小不重要，诚实知道边界在哪里才是关键。</li><li><strong>错过不亏钱，不懂才亏钱</strong>——错过<a href="/search.html?q=亚马逊">亚马逊</a>和<a href="/search.html?q=谷歌">谷歌</a>没有损失，投了不懂的公司才会造成永久性资本损失。</li><li><strong>能力圈可以演化，但不能强行突破</strong>——<a href="/03_companies/苹果公司.html">苹果</a>的案例表明，能力圈的扩展来自对商业本质的重新归类，而非对&quot;不懂&quot;领域的冒险下注。</li><li><strong>诚实是能力圈的前提</strong>——从1956年到2020年，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>最一致的品质是对公众坦诚自己的无知。</li></ol><blockquote><p>&quot;你不必成为每一家公司或者许多公司的专家。你只需要能够评估你能力范围内的公司。能力圈的大小不重要，知道它的边界在哪里才是关键。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1996年致股东信</p></blockquote><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=核心总结">1993年：核心总结</a> → <a href="/01_letters/1993年/翻译.html">/01_letters/1993年/翻译</a></li><li><a href="/search.html?q=核心总结">1996年：核心总结</a> → <a href="/01_letters/1996年/翻译.html">/01_letters/1996年/翻译</a></li><li><a href="/search.html?q=核心总结">1997年：核心总结</a> → <a href="/01_letters/1997年/翻译.html">/01_letters/1997年/翻译</a></li><li><a href="/search.html?q=核心总结">1999年：核心总结</a> → <a href="/01_letters/1999年/翻译.html">/01_letters/1999年/翻译</a></li><li><a href="/search.html?q=核心总结">2000年：核心总结</a> → <a href="/01_letters/2000年/翻译.html">/01_letters/2000年/翻译</a></li><li><a href="/search.html?q=核心总结">2003年：核心总结</a> → <a href="/01_letters/2003年/翻译.html">/01_letters/2003年/翻译</a></li><li><a href="/search.html?q=核心总结">2017年：核心总结</a> → <a href="/01_letters/2017年/翻译.html">/01_letters/2017年/翻译</a></li><li><a href="/search.html?q=核心总结">2020年：核心总结</a> → <a href="/01_letters/2020年/翻译.html">/01_letters/2020年/翻译</a></li></ul><p><strong>能力圈原则的本质是诚实的自我认知。不是扩大能力圈的半径，而是永远忠实于它的边界。</strong></p>',58)])])}const u=e(o,[["render",h]]);export{q as __pageData,u as default};
